#include "helper.hpp"
int main(){vector<int>a(5);int k=0;for(int i=0;i<5;i++)for(int j=i+1;j<5;j++,k++)if(759>>k&1)a[i]|=1<<j;else a[j]|=1<<i;a=ear(a,2);for(int pm:{50,24}){auto b=ear(a,pm);int checked=0;for(int u=0;u<128&&checked<5;u++)for(int v=0;v<128&&checked<5;v++){auto d=ear(ear(b,u),v);int h=hp(d);if(h>289)continue; int one[9], inter[9][9];for(int i=0;i<9;i++)one[i]=hp(ear(d,1<<i))-h;for(int i=0;i<9;i++)for(int j=i+1;j<9;j++)inter[i][j]=hp(ear(d,(1<<i)|(1<<j)))-h-one[i]-one[j];for(int w=0;w<512;w++){int z=h;for(int i=0;i<9;i++)if(w>>i&1){z+=one[i];for(int j=i+1;j<9;j++)if(w>>j&1)z+=inter[i][j];}if(hp(ear(d,w))!=z){cerr<<"mismatch"<<endl;return 1;}}checked++;}cout<<"parent="<<pm<<" audited="<<checked<<" 512-masks-per-parent\n";}}
